//! Validation against the g-xTB 1.1.0 program (data in tests/reference/, generated by
//! scripts/make_reference.py): input geometry handling, EEQ-BC charges, the basis CN, the
//! q-vSZP effective charges and contracted shells.

use axtb::basis::Basis;
use axtb_base::math::primitive_norm;
use axtb_gxtb::basis::{integrals, Basis as EngineBasis};
use axtb_gxtb::eeqbc::eeqbc_charges;
use axtb_gxtb::fock::shell_list;
use axtb_gxtb::params::QvszpParams;
use axtb_gxtb::read_xyz;
use serde_json::Value;
use std::path::{Path, PathBuf};

/// (atom, shell, l) of every AO of a basis.
fn ao_list(bas: &Basis) -> Vec<(usize, usize, usize)> {
    let shells = shell_list(bas);
    bas.ao2sh.iter().map(|&s| shells[s]).collect()
}

fn reference_dirs() -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/reference");
    let mut dirs: Vec<PathBuf> = std::fs::read_dir(&root)
        .expect("tests/reference")
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.join("intermediates.json").exists())
        .collect();
    dirs.sort();
    assert!(dirs.len() >= 8, "expected the reference set, found {}", dirs.len());
    dirs
}

/// SCF settings that reproduce the program (its Fock matrix).
fn program() -> axtb_gxtb::ScfOptions {
    axtb_gxtb::ScfOptions { conventions: axtb_gxtb::Conventions::Gxtb, ..Default::default() }
}

fn json(path: &Path) -> Value {
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn floats(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect()
}

struct Case {
    name: String,
    mol: axtb::Molecule,
    inter: Value,
    summary: Value,
    dir: PathBuf,
}

fn cases() -> Vec<Case> {
    reference_dirs()
        .into_iter()
        .map(|dir| {
            let input = json(&dir.join("input.json"));
            let charge = input["charge"].as_f64().unwrap();
            let uhf = input["uhf"].as_u64().unwrap() as usize;
            let xyz = std::fs::read_to_string(dir.join("mol.xyz")).unwrap();
            let mol = read_xyz(&xyz, charge, Some(uhf)).unwrap();
            Case {
                name: dir.file_name().unwrap().to_string_lossy().into_owned(),
                mol,
                inter: json(&dir.join("intermediates.json")),
                summary: json(&dir.join("summary.json")),
                dir,
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f64], b: &[f64]) -> f64 {
    assert_eq!(a.len(), b.len());
    a.iter().zip(b).map(|(x, y)| (x - y).abs()).fold(0.0, f64::max)
}

#[test]
fn coordinates_match_program() {
    for c in cases() {
        let xyz = floats(&c.inter["xyz"]["data"]);
        let ours: Vec<f64> = c.mol.positions.iter().flatten().copied().collect();
        // the program's list-directed read occasionally rounds a decimal 1 ulp differently
        let d = max_abs_diff(&ours, &xyz);
        assert!(d < 1e-15, "{}: coordinates differ by {d:e}", c.name);
    }
}

#[test]
fn eeqbc_charges_match_program() {
    let mut worst = 0.0f64;
    for c in cases() {
        let r = eeqbc_charges(&v11(), &c.mol).unwrap();
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let d = max_abs_diff(&r.charges, &q_ref);
        worst = worst.max(d);
        assert!(d < 1e-12, "{}: EEQ-BC charges differ by {d:e}", c.name);
        let sum: f64 = r.charges.iter().sum();
        assert!((sum - c.mol.charge).abs() < 1e-12);
        // printed (4 decimals) CN and local charge
        let t = &c.summary["eeq_table"];
        for (ours, key) in [(&r.cn, "cn"), (&r.qloc, "qloc")] {
            let printed = floats(&t[key]);
            let d = max_abs_diff(ours, &printed);
            assert!(d <= 5.0001e-5, "{}: printed {key} differs by {d:e}", c.name);
        }
        // printed EEQ dipole (6 decimals, bohr * e)
        let dip = floats(&c.summary["eeq_dipole_au"]);
        for (k, &d) in dip.iter().enumerate() {
            let mu: f64 = (0..c.mol.nat()).map(|i| r.charges[i] * c.mol.positions[i][k]).sum();
            assert!((mu - d).abs() <= 5.0001e-7, "{}: EEQ dipole {k}: {mu} vs {d}", c.name);
        }
    }
    eprintln!("EEQ-BC charges: max deviation {worst:e}");
}

/// The program stores primitives per Cartesian AO (atom by atom, shell by shell, ncart(l)
/// components each); the first component of each shell carries the x^l normalization.
#[test]
fn qvszp_primitives_match_program() {
    let basis = QvszpParams::v1_1();
    let mut worst = 0.0f64;
    for c in cases() {
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let qeff_ref = floats(&c.inter["qeff"]["data"]);
        let exps = floats(&c.inter["prim_exp"]["data"]);
        let cnts = floats(&c.inter["prim_cnt"]["data"]);
        let b = EngineBasis::new(&v11(), &c.mol, &q_ref).unwrap();
        let mut k = 0;
        for (iat, &z) in c.mol.numbers.iter().enumerate() {
            let raw = raw_shell_coefficients(&basis, z, qeff_ref[iat]);
            for (ish, sh) in b.scf.cgto[iat].iter().enumerate() {
                let ncart = (sh.l + 1) * (sh.l + 2) / 2;
                for comp in 0..ncart {
                    for p in 0..sh.nprim {
                        assert_eq!(exps[k], sh.alpha[p], "{}: exponent atom {iat} shell {ish}", c.name);
                        if comp == 0 {
                            let d = (cnts[k] - raw[ish][p]).abs() / raw[ish][p].abs().max(1e-300);
                            worst = worst.max(d);
                            assert!(d < 1e-13, "{}: coefficient atom {iat} shell {ish} prim {p}: rel {d:e}", c.name);
                        }
                        k += 1;
                    }
                }
            }
        }
        assert_eq!(k, exps.len(), "{}: number of primitives", c.name);
        assert_eq!(c.summary["npr"].as_u64().unwrap() as usize, k, "{}: npr", c.name);
    }
    eprintln!("q-vSZP primitive coefficients: max relative deviation {worst:e}");
}

/// Molden [GTO] section: the normalized contraction of each shell.
#[test]
fn qvszp_shells_match_molden() {
    let mut worst = 0.0f64;
    for c in cases() {
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let b = EngineBasis::new(&v11(), &c.mol, &q_ref).unwrap();
        let text = std::fs::read_to_string(c.dir.join("molden.input")).unwrap();
        let gto = text.split("[GTO]").nth(1).unwrap().split("[MO]").next().unwrap();
        let mut lines = gto.lines().map(str::trim).filter(|l| !l.is_empty()).peekable();
        let mut iat = 0;
        while let Some(head) = lines.next() {
            // atom header "n 0"
            let atom: usize = head.split_whitespace().next().unwrap().parse().unwrap();
            assert_eq!(atom, iat + 1);
            let mut ish = 0;
            while let Some(&l) = lines.peek() {
                let f: Vec<&str> = l.split_whitespace().collect();
                if f.len() == 2 && f[1] == "0" {
                    break;
                }
                lines.next();
                let nprim: usize = f[1].parse().unwrap();
                let sh = &b.scf.cgto[iat][ish];
                assert_eq!(nprim, sh.nprim);
                assert_eq!("spdfg".find(f[0]).unwrap(), sh.l, "{}: shell type", c.name);
                for p in 0..nprim {
                    let v: Vec<f64> = lines
                        .next()
                        .unwrap()
                        .split_whitespace()
                        .map(|x| x.replace('D', "E").parse().unwrap())
                        .collect();
                    assert_eq!(v[0], sh.alpha[p]);
                    let d = (v[1] - sh.coeff[p]).abs() / v[1].abs();
                    worst = worst.max(d);
                    assert!(d < 1e-12, "{}: molden coefficient atom {iat} shell {ish}: rel {d:e}", c.name);
                }
                ish += 1;
            }
            assert_eq!(ish, b.scf.cgto[iat].len(), "{}: shells of atom {iat}", c.name);
            iat += 1;
        }
        assert_eq!(iat, c.mol.nat());
    }
    eprintln!("molden contraction coefficients: max relative deviation {worst:e}");
}

/// Overlap matrix of the q-vSZP basis (normalized AOs), checked through the program's MOs:
/// the molden MO coefficients (15 digits) must satisfy C^T S C = 1 with our S. Molecules with
/// s and p shells only (molden writes Cartesian d/f functions transformed from spherical,
/// which needs the program's Cartesian convention; not covered yet).
#[test]
fn overlap_orthonormalizes_program_mos() {
    use axtb::integrals::{overlap, MBLK};
    let mut worst = 0.0f64;
    let mut ntested = 0;
    for c in cases() {
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let b = EngineBasis::new(&v11(), &c.mol, &q_ref).unwrap();
        if b.scf.cgto.iter().flatten().any(|s| s.l > 1) {
            continue;
        }
        // AO list in molden order: atom, shell, (s) or (x, y, z)
        let mut aos = Vec::new(); // (atom, shell, spherical index in axtb order)
        for (iat, sh) in b.scf.cgto.iter().enumerate() {
            for (ish, s) in sh.iter().enumerate() {
                match s.l {
                    0 => aos.push((iat, ish, 0)),
                    _ => aos.extend([(iat, ish, 2), (iat, ish, 0), (iat, ish, 1)]), // x, y, z <- axtb (y, z, x)
                }
            }
        }
        let n = aos.len();
        let mut s = vec![0.0; n * n];
        let mut blk = [0.0; MBLK];
        for (i, &(ia, is, im)) in aos.iter().enumerate() {
            for (j, &(ja, js, jm)) in aos.iter().enumerate() {
                let (ci, cj) = (&b.scf.cgto[ia][is], &b.scf.cgto[ja][js]);
                let ri = c.mol.positions[ia];
                let rj = c.mol.positions[ja];
                let vec = [ri[0] - rj[0], ri[1] - rj[1], ri[2] - rj[2]];
                overlap(cj, ci, vec, f64::INFINITY, &mut blk);
                let nsj = 2 * cj.l + 1;
                s[i * n + j] = blk[jm + nsj * im];
            }
        }
        // molden MOs
        let text = std::fs::read_to_string(c.dir.join("molden.input")).unwrap();
        let mo_text = text.split("[MO]").nth(1).unwrap();
        let mut mos: Vec<(String, Vec<f64>)> = Vec::new();
        for block in mo_text.split("Sym=").skip(1) {
            let spin = block.lines().find(|l| l.trim_start().starts_with("Spin=")).unwrap().to_string();
            let mut coef = vec![0.0; n];
            for l in block.lines() {
                let f: Vec<&str> = l.split_whitespace().collect();
                if f.len() == 2 {
                    if let (Ok(k), Ok(v)) = (f[0].parse::<usize>(), f[1].replace('D', "E").parse::<f64>()) {
                        coef[k - 1] = v;
                    }
                }
            }
            mos.push((spin, coef));
        }
        for (a, (spa, ca)) in mos.iter().enumerate() {
            for (bidx, (spb, cb)) in mos.iter().enumerate().skip(a) {
                if spa != spb {
                    continue;
                }
                let mut x = 0.0;
                for i in 0..n {
                    for j in 0..n {
                        x += ca[i] * s[i * n + j] * cb[j];
                    }
                }
                let d = (x - if a == bidx { 1.0 } else { 0.0 }).abs();
                worst = worst.max(d);
                assert!(d < 1e-10, "{}: C^T S C ({a},{bidx}) = {x}", c.name);
            }
        }
        ntested += 1;
    }
    assert!(ntested >= 8);
    eprintln!("overlap: max |C^T S C - 1| = {worst:e} over {ntested} molecules");
}

/// The program orders spherical d functions as (x2-y2, z2, xy, xz, yz), i.e. axtb offsets
/// m = +2, 0, -2, +1, -1.
const PROGRAM_D_ORDER: [usize; 5] = [4, 2, 0, 3, 1];

/// Program AO index -> our AO index (axtb order). The program orders p as x, y, z.
fn program_ao_map(ao: &[(usize, usize, usize)], dperm: [usize; 5]) -> Vec<usize> {
    let mut map = Vec::with_capacity(ao.len());
    let mut k = 0;
    while k < ao.len() {
        let l = ao[k].2;
        match l {
            0 => map.push(k),
            1 => map.extend([k + 2, k, k + 1]),
            2 => map.extend(dperm.iter().map(|&m| k + m)),
            _ => map.extend(k..k + 2 * l + 1),
        }
        k += 2 * l + 1;
    }
    map
}

/// Program packed matrix (program AO order) -> full matrix in our AO order.
fn unpack_program(packed: &[f64], map: &[usize]) -> Vec<f64> {
    let n = map.len();
    let mut m = vec![0.0; n * n];
    let mut k = 0;
    for i in 0..n {
        for j in 0..=i {
            m[map[i] * n + map[j]] = packed[k];
            m[map[j] * n + map[i]] = packed[k];
            k += 1;
        }
    }
    m
}

/// Converged spin densities of the program in our AO order.
fn program_densities(c: &Case, map: &[usize]) -> Vec<Vec<f64>> {
    let r = json(&c.dir.join("scf.json"));
    let n = map.len();
    let npk = n * (n + 1) / 2;
    let p = floats(&r["p_packed"]);
    (0..r["nspin"].as_u64().unwrap() as usize).map(|sp| unpack_program(&p[sp * npk..(sp + 1) * npk], map)).collect()
}

// ---- the same checks on the engine's v1.1 model (step 17) ----

/// The engine's v1.1 model in the program's conventions.
fn v11() -> axtb_gxtb::model::Model {
    axtb_gxtb::model::Model::v1_1(axtb_gxtb::Conventions::Gxtb)
}

/// The engine's v1.1 isotropic potential and kernel against the old tree's potential and
/// central differences of the engine's potential, at the program's charges.
#[test]
fn isotropic_engine_potential_and_kernel() {
    use axtb_gxtb::cn::gxtb_cn;
    use axtb_gxtb::coulomb::IsotropicCache;
    let mut wk = 0.0f64;
    for c in cases() {
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let b = EngineBasis::new(&v11(), &c.mol, &q_ref).unwrap();
        let q = floats(&json(&c.dir.join("scf.json"))["shell_charges"]);
        let cn = gxtb_cn(&v11(), &c.mol);
        let sh = shell_list(&b.scf);
        let iso = IsotropicCache::new(&v11(), &c.mol, &sh, &cn);
        // the kernel (Hessian-vector product) against central differences of the potential
        let dq: Vec<f64> = (0..q.len()).map(|i| ((7 * i + 3) % 11) as f64 / 11.0 - 0.5).collect();
        let h = 1e-5;
        let at = |s: f64| iso.potential(&q.iter().zip(&dq).map(|(a, b)| a + s * b).collect::<Vec<_>>(), false);
        let (vp, vm) = (at(h), at(-h));
        let fd: Vec<f64> = vp.iter().zip(&vm).map(|(a, b)| (a - b) / (2.0 * h)).collect();
        let k = iso.hessian_vec(&q, &dq);
        wk = wk.max(max_abs_diff(&fd, &k));
        assert!(max_abs_diff(&fd, &k) < 1e-7, "{}: kernel vs FD {:e}", c.name, max_abs_diff(&fd, &k));
    }
    eprintln!("engine isotropic kernel vs FD {wk:e}");
}

/// The engine's v1.1 EEQ-BC charges, coordination numbers, effective charges, SCF overlap, H0
/// and ACP against the old tree (the same bits where the expressions are the program's) and
/// the program.
#[test]
fn basis_and_one_electron_engine_match_program() {
    use axtb_gxtb::basis::{integrals, Basis};
    use axtb_gxtb::cn::gxtb_cn;
    use axtb_gxtb::h0::{add_acp, build_h0, selfenergy, AcpSet};
    let model = v11();
    let (mut ws, mut wh, mut wa) = (0.0f64, 0.0f64, 0.0f64);
    for c in cases() {
        let mol = &c.mol;
        let cn = gxtb_cn(&model, mol);
        // basis CN and effective charges from the program's charges, and end to end
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let b = Basis::new(&model, mol, &q_ref).unwrap();
        let (cn_ref, qeff_ref) = (floats(&c.inter["cn_eeq"]["data"]), floats(&c.inter["qeff"]["data"]));
        assert!(max_abs_diff(&b.cn, &cn_ref) < 1e-13, "{}: basis CN", c.name);
        assert!(max_abs_diff(&b.qeff, &qeff_ref) < 1e-13, "{}: q_eff", c.name);
        let setup = engine_setup(mol);
        assert!(max_abs_diff(&setup.basis.qeff, &qeff_ref) < 1e-12, "{}: end-to-end q_eff", c.name);
        // SCF overlap (every pair evaluated in both orders and averaged)
        let (s, _, _) = integrals(mol, &b.scf, b.pair_cutoff(&model), false);
        let ao = ao_list(&b.scf);
        let map = program_ao_map(&ao, PROGRAM_D_ORDER);
        let n = ao.len();
        let sp = floats(&json(&c.dir.join("scf.json"))["s_packed"]);
        let mut k = 0;
        for i in 0..n {
            for j in 0..=i {
                let d = (s[map[i] * n + map[j]] - sp[k]).abs();
                ws = ws.max(d);
                assert!(d < 1e-13, "{}: S({i},{j}) = {} vs {}", c.name, s[map[i] * n + map[j]], sp[k]);
                k += 1;
            }
        }
        // H0 (lower triangle, then mirrored) and H0 + ACP
        let r = json(&c.dir.join("h0.json"));
        let nh = b.h0.nao;
        assert_eq!(r["nsao"].as_u64().unwrap() as usize, nh, "{}: nao", c.name);
        let mut h = build_h0(&model, mol, &b.h0, &cn, b.pair_cutoff(&model), false);
        let mut h0 = h.clone();
        axtb_gxtb::parallel::mirror_lower(&mut h0, nh, false);
        let set = AcpSet::new(&model, mol, &cn, b.pair_cutoff(&model));
        add_acp(mol, &b.scf, &set, &mut h, faer::Par::Seq, false);
        axtb_gxtb::parallel::mirror_lower(&mut h, nh, false);
        let hmap = program_ao_map(&ao_list(&b.h0), PROGRAM_D_ORDER);
        let (hp, ha, lv) = (floats(&r["h0_packed"]), floats(&r["h0_acp_packed"]), floats(&r["levels"]));
        let shells = shell_list(&b.h0);
        let mut k = 0;
        for i in 0..nh {
            let (iat, ish, _) = shells[b.h0.ao2sh[hmap[i]]];
            let level = selfenergy(&model, mol.numbers[iat], ish, cn[iat]).0;
            assert!((-level - lv[i]).abs() < 1e-14, "{}: level {i}", c.name);
            for j in 0..=i {
                let (x, y) = (hmap[i], hmap[j]);
                let (dh, da) = ((h0[x * nh + y] - hp[k]).abs(), (h[x * nh + y] - ha[k]).abs());
                wh = wh.max(dh);
                wa = wa.max(da);
                assert!(dh < 1e-12, "{}: H0({i},{j}) = {} vs {}", c.name, h0[x * nh + y], hp[k]);
                assert!(da < 1e-12, "{}: H0+ACP({i},{j}) = {} vs {}", c.name, h[x * nh + y], ha[k]);
                k += 1;
            }
        }
    }
    eprintln!("engine v1.1: S {ws:e}, H0 {wh:e}, H0 + ACP {wa:e} (max abs deviation from the program)");
}

/// The engine's v1.1 exchange (MFX and the dual-density onsite exchange) against the program's
/// energies at its densities, and its Fock matrices, overlap weight and response against the
/// old tree and central differences.
#[test]
fn exchange_engine_matches_program() {
    use axtb_gxtb::exchange::Exchange;
    use faer::Par;
    let model = v11();
    let (mut wm, mut wo, mut wr) = (0.0f64, 0.0f64, 0.0f64);
    for c in cases() {
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let b = EngineBasis::new(&model, &c.mol, &q_ref).unwrap();
        let n = b.scf.nao;
        let sh = shell_list(&b.scf);
        let map = program_ao_map(&ao_list(&b.scf), PROGRAM_D_ORDER);
        let dens = program_densities(&c, &map);
        let ex = Exchange::new(&model, &c.mol, &sh, &b.scf.ao2sh, false);
        let s = &integrals(&c.mol, &b.scf, b.pair_cutoff(&model), false).0;
        let pr = ex.products(s, &dens, Par::Seq);
        let q = vec![0.0; sh.len()];
        let (e_mfx, e_ofx, _, _) = ex.evaluate_parts(s, &dens, &pr, &q, false, Par::Seq, false);
        let fe = &json(&c.dir.join("kernels.json"))["final_energies"];
        let (rm, ro) = (fe["mfx"].as_f64().unwrap(), fe["ofx"].as_f64().unwrap());
        wm = wm.max((e_mfx - rm).abs());
        wo = wo.max((e_ofx - ro).abs());
        assert!((e_mfx - rm).abs() < 1e-11, "{}: E_MFX {e_mfx} vs {rm}", c.name);
        assert!((e_ofx - ro).abs() < 1e-12, "{}: E_OFX {e_ofx} vs {ro}", c.name);
        // response: the change of the Fock matrices along a density change (exact: quadratic in P)
        let base = ex.response_base(s, &dens, &q, Par::Seq);
        let dp: Vec<Vec<f64>> = dens
            .iter()
            .map(|p| (0..n * n).map(|x| ((x % n + x / n) % 7) as f64 * 1e-2 + 0.1 * p[x]).collect())
            .collect();
        let (df, _, _) = ex.response(s, &dens, &base, &dp, &q, Par::Seq);
        let h = 1e-3;
        let at = |sg: f64| {
            let pp: Vec<Vec<f64>> =
                dens.iter().zip(&dp).map(|(a, b)| a.iter().zip(b).map(|(x, y)| x + sg * h * y).collect()).collect();
            let prp = ex.products(s, &pp, Par::Seq);
            ex.evaluate_parts(s, &pp, &prp, &q, true, Par::Seq, false).2
        };
        let (fp, fmm) = (at(1.0), at(-1.0));
        for k in 0..dens.len() {
            let d = (0..n * n).map(|x| ((fp[k][x] - fmm[k][x]) / (2.0 * h) - df[k][x]).abs()).fold(0.0, f64::max);
            wr = wr.max(d);
            assert!(d < 1e-9, "{}: exchange response (spin {k}) vs FD {d:e}", c.name);
        }
    }
    eprintln!("engine v1.1 exchange: E_MFX {wm:e}, E_OFX {wo:e} Eh; response vs FD {wr:e}");
}

/// The engine's v1.1 revD4 (rational two-body damping with C8, zero-damped three-body term) and
/// semi-classical repulsion against the program, and their gradients against central
/// differences.
#[test]
fn revd4_and_repulsion_engine_match_program() {
    use axtb_gxtb::cn::gxtb_cn;
    use axtb_gxtb::repulsion::classical;
    use axtb_gxtb::revd4::RevD4;
    let model = v11();
    let (mut w2, mut w3, mut wr, mut wg) = (0.0f64, 0.0f64, 0.0f64, 0.0f64);
    for c in cases() {
        let mol = &c.mol;
        let d = RevD4::new(&model, mol).unwrap();
        let q = floats(&json(&c.dir.join("scf.json"))["atom_charges"]);
        let fe = &json(&c.dir.join("kernels.json"))["final_energies"];
        let (e2, e3) = (d.two_body(&q).0, d.three_body(&model, mol, None).0);
        let (r2, r3) = (fe["disp2"].as_f64().unwrap(), fe["disp3"].as_f64().unwrap());
        w2 = w2.max((e2 - r2).abs());
        w3 = w3.max((e3 - r3).abs());
        assert!((e2 - r2).abs() < 1e-14, "{}: revD4 two-body {e2:.17} vs {r2:.17}", c.name);
        assert!((e3 - r3).abs() < 1e-15, "{}: revD4 ATM {e3:.17} vs {r3:.17}", c.name);
        let qe = axtb_gxtb::eeqbc::eeqbc_charges(&model, mol).unwrap().charges;
        let cn = gxtb_cn(&model, mol);
        let erep = classical::energy(mol, &qe, &cn, None);
        let dr = (erep - c.inter["repulsion_energy"].as_f64().unwrap()).abs();
        wr = wr.max(dr);
        assert!(dr < 1e-12, "{}: repulsion {erep:.16} vs {}", c.name, c.inter["repulsion_energy"]);
        // gradients at fixed charges and CNs (positions only) against central differences
        let n = mol.nat();
        let mut g = vec![[0.0; 3]; n];
        d.two_body_gradient(&model, mol, &q, &mut g);
        d.three_body(&model, mol, Some(&mut g));
        let (mut gq, mut gc) = (vec![0.0; n], vec![0.0; n]);
        classical::energy(mol, &qe, &cn, Some((&mut g, &mut gq, &mut gc)));
        let h = 1e-5;
        for a in 0..n.min(3) {
            for x in 0..3 {
                let e = |s: f64| {
                    let mut m = mol.clone();
                    m.positions[a][x] += s * h;
                    // the same CNs (fixed), so only the explicit position dependence
                    let dd = RevD4::with_cn(&model, &m, d.cn.clone()).unwrap();
                    dd.two_body(&q).0 + dd.three_body(&model, &m, None).0 + classical::energy(&m, &qe, &cn, None)
                };
                let fd = (e(1.0) - e(-1.0)) / (2.0 * h);
                wg = wg.max((fd - g[a][x]).abs());
                assert!((fd - g[a][x]).abs() < 1e-8, "{}: gradient {a} {x}: {} vs FD {fd}", c.name, g[a][x]);
            }
        }
    }
    eprintln!("engine v1.1 revD4: two-body {w2:e}, three-body {w3:e}; repulsion {wr:e} Eh; gradients vs FD {wg:e}");
}

/// The engine's v1.1 setup in the program's conventions.
fn engine_setup(mol: &axtb::Molecule) -> axtb_gxtb::scf::Setup {
    axtb_gxtb::scf::Setup::new(mol, v11()).unwrap()
}

/// The AOs ((atom, shell, l)) of the engine's setup.
fn engine_ao(s: &axtb_gxtb::scf::Setup) -> Vec<(usize, usize, usize)> {
    s.basis.scf.ao2sh.iter().map(|&ish| s.shells[ish]).collect()
}

/// The engine's v1.1 Fock matrices in the program's conventions at the program's densities.
#[test]
fn fock_engine_matches_program() {
    let mut worst = 0.0f64;
    for c in cases() {
        let setup = engine_setup(&c.mol);
        let map = program_ao_map(&engine_ao(&setup), PROGRAM_D_ORDER);
        let n = setup.nao;
        let npk = n * (n + 1) / 2;
        let r = json(&c.dir.join("fock.json"));
        let tol = if c.name == "tetrachlorocuprate" { 3e-9 } else { 1e-12 };
        for key in ["first", "last"] {
            let ns = r[key]["nspin"].as_u64().unwrap() as usize;
            assert_eq!(ns, setup.nspin);
            let (pp, ff) = (floats(&r[key]["P"]), floats(&r[key]["F"]));
            let p: Vec<Vec<f64>> = (0..ns).map(|s| unpack_program(&pp[s * npk..(s + 1) * npk], &map)).collect();
            let (_, fock) = setup.evaluate(&setup.state(&p), true);
            for s in 0..ns {
                let f = unpack_program(&ff[s * npk..(s + 1) * npk], &map);
                let d = max_abs_diff(&fock[s], &f);
                if c.name != "tetrachlorocuprate" {
                    worst = worst.max(d);
                }
                assert!(d < tol, "{}: Fock ({key}, spin {s}) differs by {d:e}", c.name);
            }
        }
    }
    eprintln!("engine Fock matrices at the program's densities: max deviation {worst:e} (excl. [CuCl4]2-)");
}

/// The engine's v1.1 single points in the program's conventions against the program, as
/// [`scf_matches_program`].
#[test]
fn scf_engine_matches_program() {
    let (mut we, mut wt, mut wq, mut weps) = (0.0f64, 0.0f64, 0.0f64, 0.0f64);
    for c in cases() {
        let r = engine_setup(&c.mol).scf(&program()).unwrap();
        let e = &r.energies;
        let eref = c.summary["total_energy"].as_f64().unwrap();
        we = we.max((e.total - eref).abs());
        assert!((e.total - eref).abs() < 1e-11, "{}: total {:.13} vs {eref:.13}", c.name, e.total);
        assert_eq!(r.iterations as u64, c.summary["scf_iterations"].as_u64().unwrap(), "{}: iterations", c.name);
        let fe = &json(&c.dir.join("kernels.json"))["final_energies"];
        let es23 = e.second_order + e.third_order + e.fourth_order;
        let terms = [
            ("es1", e.first_order),
            ("es2_3", es23),
            ("ofx", e.exchange_onsite),
            ("mfx", e.exchange),
            ("aes", e.aes),
            ("disp2", e.dispersion),
            ("disp3", e.dispersion_three_body),
        ];
        for (k, v) in terms.into_iter().chain(fe.get("spin").map(|_| ("spin", e.spin))) {
            let d = (v - fe[k].as_f64().unwrap()).abs();
            wt = wt.max(d);
            assert!(d < 1e-11, "{}: {k} {v:.14} vs {}", c.name, fe[k]);
        }
        let t = &c.summary["energy_terms"];
        for (k, v) in [
            ("electronic", e.electronic),
            ("atomic core increments", e.increments),
            ("dispersion", e.dispersion),
            ("nuclear repulsion", e.repulsion),
            ("ES total", e.first_order + es23 + e.aes),
            ("total", e.total),
        ] {
            assert!((v - t[k].as_f64().unwrap()).abs() <= 5.0001e-9, "{}: printed {k} {} vs {v}", c.name, t[k]);
        }
        let scf = json(&c.dir.join("scf.json"));
        for (ours, key) in [(&r.atom_charges, "atom_charges"), (&r.shell_charges, "shell_charges")] {
            let d = max_abs_diff(ours, &floats(&scf[key]));
            wq = wq.max(d);
            assert!(d < 1e-10, "{}: {key} differ by {d:e}", c.name);
        }
        let text = std::fs::read_to_string(c.dir.join("molden.input")).unwrap();
        let mut eps_ref: Vec<Vec<f64>> = vec![Vec::new(); r.orbital_energies.len()];
        for block in text.split("[MO]").nth(1).unwrap().split("Sym=").skip(1) {
            let ene: f64 = block.lines().find_map(|l| l.trim().strip_prefix("Ene=")).unwrap().trim().parse().unwrap();
            let beta = block.contains("Spin= Beta");
            eps_ref[if beta { 1 } else { 0 }].push(ene);
        }
        let tol = if c.name == "tetrachlorocuprate" { 2e-9 } else { 1e-10 };
        for (s, er) in eps_ref.iter().enumerate() {
            let d = max_abs_diff(&r.orbital_energies[s][..er.len()], er);
            if c.name != "tetrachlorocuprate" {
                weps = weps.max(d);
            }
            assert!(d < tol, "{}: orbital energies (spin {s}) differ by {d:e}", c.name);
        }
    }
    eprintln!(
        "engine SCF: total energy {we:e} Eh, terms {wt:e} Eh, charges {wq:e}, orbital energies {weps:e} Eh (excl. [CuCl4]2-)"
    );
}

/// The engine's v1.1 single points of tests/reference_extra.json, as
/// [`extra_singlepoints_match_program`].
#[test]
fn extra_singlepoints_engine_match_program() {
    let r = json(&Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/reference_extra.json"));
    let mut worst = 0.0f64;
    for m in r["molecules"].as_array().unwrap() {
        let name = m["name"].as_str().unwrap();
        let mol = read_xyz(
            m["xyz"].as_str().unwrap(),
            m["charge"].as_f64().unwrap(),
            Some(m["uhf"].as_u64().unwrap() as usize),
        )
        .unwrap();
        let res = engine_setup(&mol).scf(&program()).unwrap();
        let eref = m["total_energy"].as_f64().unwrap();
        let d = (res.energies.total - eref).abs();
        worst = worst.max(d);
        assert!(d < 1e-10, "{name}: total {:.12} vs {eref:.12}", res.energies.total);
        assert_eq!(res.iterations as u64, m["scf_iterations"].as_u64().unwrap(), "{name}: iterations");
    }
    eprintln!("engine extra single points: max total-energy deviation {worst:e} Eh");
}

/// The program's internal (unnormalized-contraction) coefficients of a shell:
/// (c0 + c1 q_eff) times the primitive normalization of the x^l component.
fn raw_shell_coefficients(basis: &QvszpParams, z: usize, qeff: f64) -> Vec<Vec<f64>> {
    let el = basis.element(z).unwrap();
    el.shells
        .iter()
        .map(|sh| {
            (0..sh.alpha.len()).map(|i| (sh.c0[i] + sh.c1[i] * qeff) * primitive_norm(sh.l, sh.alpha[i])).collect()
        })
        .collect()
}

/// The program's data of the reference set with the engine's v1.1 pieces: q-vSZP from the
/// program's EEQ-BC charges, the SCF overlap and Mulliken analysis of the program's density.
struct ProgramPieces {
    b: EngineBasis,
    s: Vec<f64>,
    dpint: [Vec<f64>; 3],
    qpint: [Vec<f64>; 6],
    dens: Vec<Vec<f64>>,
    ptot: Vec<f64>,
}

fn program_pieces(c: &Case) -> ProgramPieces {
    let q_ref = floats(&c.inter["q_eeq"]["data"]);
    let b = EngineBasis::new(&v11(), &c.mol, &q_ref).unwrap();
    let (s, dpint, qpint) = integrals(&c.mol, &b.scf, b.pair_cutoff(&v11()), false);
    let map = program_ao_map(&ao_list(&b.scf), PROGRAM_D_ORDER);
    let dens = program_densities(c, &map);
    let n = b.scf.nao;
    let ptot: Vec<f64> = (0..n * n).map(|x| dens.iter().map(|d| d[x]).sum()).collect();
    ProgramPieces { b, s, dpint, qpint, dens, ptot }
}

/// The second-order kernel gamma and the Mulliken-exchange kernel against the program's.
#[test]
fn kernels_match_program() {
    use axtb_gxtb::cn::gxtb_cn;
    use axtb_gxtb::coulomb::IsotropicCache;
    use axtb_gxtb::exchange::Exchange;
    let (mut w2, mut wx) = (0.0f64, 0.0f64);
    for c in cases() {
        let r = json(&c.dir.join("kernels.json"));
        let q_ref = floats(&c.inter["q_eeq"]["data"]);
        let b = EngineBasis::new(&v11(), &c.mol, &q_ref).unwrap();
        let cn = gxtb_cn(&v11(), &c.mol);
        let sh = shell_list(&b.scf);
        let ns = sh.len();
        assert_eq!(r["nsh"].as_u64().unwrap() as usize, ns);
        let g2 = IsotropicCache::new(&v11(), &c.mol, &sh, &cn).gamma;
        let g2p = floats(&r["gamma2_packed"]);
        let mut k = 0;
        for i in 0..ns {
            for j in 0..=i {
                let d = (g2[i * ns + j] - g2p[k]).abs();
                w2 = w2.max(d);
                assert!(d < 1e-13, "{}: gamma2({i},{j}) {} vs {}", c.name, g2[i * ns + j], g2p[k]);
                k += 1;
            }
        }
        let gx = Exchange::new(&v11(), &c.mol, &sh, &b.scf.ao2sh, false).gx;
        let map = program_ao_map(&ao_list(&b.scf), PROGRAM_D_ORDER);
        let n = b.scf.nao;
        let gxp = floats(&r["gamma_mfx"]);
        for i in 0..n {
            for j in 0..n {
                let ours = gx[map[i] * n + map[j]];
                let d = (ours - gxp[i * n + j]).abs();
                wx = wx.max(d);
                assert!(d < 1e-13, "{}: gamma_mfx({i},{j}) {} vs {}", c.name, ours, gxp[i * n + j]);
            }
        }
    }
    eprintln!("kernels: gamma2 {w2:e}, gamma_mfx {wx:e}");
}

/// Mulliken shell charges of the program's density.
#[test]
fn mulliken_charges_match_program() {
    let mut worst = 0.0f64;
    for c in cases() {
        let pc = program_pieces(&c);
        let n0 = engine_setup(&c.mol).ref_occ;
        let q = axtb_gxtb::mulliken::shell_charges(&pc.b.scf, &pc.s, &n0, &pc.ptot, false);
        let d = max_abs_diff(&q, &floats(&json(&c.dir.join("scf.json"))["shell_charges"]));
        worst = worst.max(d);
        assert!(d < 1e-12, "{}: shell charges differ by {d:e}", c.name);
    }
    eprintln!("Mulliken shell charges at the program's density: max deviation {worst:e}");
}

/// The semi-classical repulsion and the atomic increments of the engine's v1.1 setup.
#[test]
fn repulsion_and_increments_match_program() {
    let mut worst = 0.0f64;
    for c in cases() {
        let terms = &c.summary["energy_terms"];
        let setup = engine_setup(&c.mol);
        let erep = setup.e_rep;
        let d = (erep - terms["nuclear repulsion"].as_f64().unwrap()).abs();
        assert!(d <= 5.0001e-9, "{}: repulsion {erep:.10} vs {}", c.name, terms["nuclear repulsion"]);
        // full precision, read from the program's memory
        let d = (erep - c.inter["repulsion_energy"].as_f64().unwrap()).abs();
        worst = worst.max(d);
        assert!(d < 1e-12, "{}: repulsion {erep:.16} vs {}", c.name, c.inter["repulsion_energy"]);
        let einc = setup.e_incr;
        let d = (einc - terms["atomic core increments"].as_f64().unwrap()).abs();
        assert!(d <= 5.0001e-9, "{}: increments {einc:.10} vs {}", c.name, terms["atomic core increments"]);
    }
    eprintln!("repulsion: max deviation {worst:e} Eh");
}

/// The isotropic electrostatics (first to fourth order) at the program's density.
#[test]
fn isotropic_engine_matches_program() {
    use axtb_gxtb::cn::gxtb_cn;
    use axtb_gxtb::coulomb::IsotropicCache;
    let (mut w1, mut w23) = (0.0f64, 0.0f64);
    for c in cases() {
        let pc = program_pieces(&c);
        let n0 = engine_setup(&c.mol).ref_occ;
        let q = axtb_gxtb::mulliken::shell_charges(&pc.b.scf, &pc.s, &n0, &pc.ptot, false);
        let cn = gxtb_cn(&v11(), &c.mol);
        let iso = IsotropicCache::new(&v11(), &c.mol, &shell_list(&pc.b.scf), &cn);
        let [e1, e2, e3, e4] = iso.energies(&q, false);
        let fe = &json(&c.dir.join("kernels.json"))["final_energies"];
        let d1 = (e1 - fe["es1"].as_f64().unwrap()).abs();
        let d23 = (e2 + e3 + e4 - fe["es2_3"].as_f64().unwrap()).abs();
        w1 = w1.max(d1);
        w23 = w23.max(d23);
        assert!(d1 < 1e-12, "{}: ES1 {e1} vs {}", c.name, fe["es1"]);
        assert!(d23 < 1e-12, "{}: ES2+3 {} vs {}", c.name, e2 + e3 + e4, fe["es2_3"]);
    }
    eprintln!("engine isotropic ES at the program's density: ES1 {w1:e}, ES2+3 {w23:e} Eh");
}

/// The anisotropic electrostatics and the spin polarization at the program's density.
#[test]
fn aes_and_spin_engine_match_program() {
    use axtb_gxtb::cn::gxtb_cn;
    use axtb_gxtb::coulomb::{spin_energy, AesCache};
    let mut we = 0.0f64;
    let mut n_open = 0;
    for c in cases() {
        let kr = json(&c.dir.join("kernels.json"));
        let cn = gxtb_cn(&v11(), &c.mol);
        let aes = AesCache::new(&v11(), &c.mol, &cn);
        let pc = program_pieces(&c);
        let (_, dip, qp) =
            axtb_gxtb::mulliken::moments_by_rows(&pc.b.scf, &pc.s, &pc.dpint, &pc.qpint, &pc.ptot, false);
        let qa = floats(&json(&c.dir.join("scf.json"))["atom_charges"]);
        let e = aes.energy(&c.mol, &qa, &dip, &qp, false);
        let e_ref = kr["final_energies"]["aes"].as_f64().unwrap();
        we = we.max((e - e_ref).abs());
        assert!((e - e_ref).abs() < 1e-13, "{}: E_AES {e} vs {e_ref}", c.name);
        let Some(e_ref) = kr["final_energies"].get("spin").and_then(|v| v.as_f64()) else { continue };
        let pa = axtb_gxtb::mulliken::shell_populations(&pc.b.scf, &pc.s, &pc.dens[0], false);
        let pb = axtb_gxtb::mulliken::shell_populations(&pc.b.scf, &pc.s, &pc.dens[1], false);
        let mag: Vec<f64> = pa.iter().zip(&pb).map(|(a, b)| a - b).collect();
        let e = spin_energy(&v11(), &c.mol, &shell_list(&pc.b.scf), &mag);
        assert!((e - e_ref).abs() < 1e-14, "{}: E_spin {e} vs {e_ref}", c.name);
        n_open += 1;
    }
    assert_eq!(n_open, 2);
    eprintln!("engine AES energy at the program's density: {we:e} Eh");
}
